-- 2027–28 curriculum schedule recommendations; generated by development Supabase migration history.
-- 20261113221859 catalog_edition_schedule_recommendations. Applied to development only.
begin;

create table public.catalog_edition_schedule_recommendations (
  release_id uuid not null,
  source_edition_id text not null,
  source_schedule_id text not null,
  display_text text not null,
  sessions_per_week integer check (sessions_per_week is null or sessions_per_week >= 0),
  weekly_plus boolean not null default false,
  minutes_per_session integer check (minutes_per_session is null or minutes_per_session >= 0),
  minutes_plus boolean not null default false,
  lesson_period text check (lesson_period in ('*', '_', '*or_') or lesson_period is null),
  teacher_attention text,
  grade_band text,
  extra_note text,
  primary key (release_id, source_edition_id, source_schedule_id),
  foreign key (release_id, source_edition_id)
    references public.catalog_editions (release_id, source_edition_id)
    on delete cascade
);

create index catalog_schedule_recommendations_edition_idx
  on public.catalog_edition_schedule_recommendations (release_id, source_edition_id);

alter table public.catalog_edition_schedule_recommendations enable row level security;
revoke all privileges on table public.catalog_edition_schedule_recommendations from public, anon, authenticated;

commit;
